const repointCustomer = `-- name: RepointCustomer :execrows
UPDATE invoices.invoices SET
    customer_id = $1,
    revision = CASE WHEN status = 'draft' THEN revision + 1 ELSE revision END,
    updated_at = CASE WHEN status = 'draft' THEN $2::timestamptz ELSE updated_at END
WHERE customer_id = $3
`

type RepointCustomerParams struct {
	IntoCustomerID int32
	Now            time.Time
	FromCustomerID int32
}

// RepointCustomer moves every document of one customer to another (D10), the
// merge holder's one write, inside the merge's transaction. A draft's revision
// and updated_at move as any change to it does; an issued document's do not —
// the trigger allows exactly the customer_id to change on it (D9), and its
// buyer snapshot, which is what it printed, is untouched.
func (q *Queries) RepointCustomer(ctx context.Context, arg RepointCustomerParams) (int64, error) {
	result, err := q.db.Exec(ctx, repointCustomer, arg.IntoCustomerID, arg.Now, arg.FromCustomerID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

